commands:
set -euo pipefail
mkdir -p /tmp/log_analysis
# Find files in /work/logs modified in last 24 hours
find /work/logs -type f -newermt '1 day ago' > /tmp/log_analysis/logfiles.txt 2>/dev/null || true
LOGFILES_CONTENT=$(cat /tmp/log_analysis/logfiles.txt || true)
if [ -z "$LOGFILES_CONTENT" ]; then
  # fallback: if no files modified in last 24h, consider all log files
  find /work/logs -type f > /tmp/log_analysis/logfiles.txt || true
fi
# Grep relevant error lines (case-insensitive) from these files
xargs -a /tmp/log_analysis/logfiles.txt -r --no-run-if-empty grep -iHn -E 'error|exception|fail|fatal|traceback' 2>/dev/null > /tmp/log_analysis/errors_raw.txt || true
ERROR_LINES=$(wc -l < /tmp/log_analysis/errors_raw.txt 2>/dev/null || true)
# Prepare cleaned message lines (remove filename:line: prefix)
cut -d: -f3- /tmp/log_analysis/errors_raw.txt | sed 's/^[[:space:]]*//' > /tmp/log_analysis/errors_only.txt || true
# Top 40 distinct lines
cat /tmp/log_analysis/errors_only.txt | sed 's/\s\+/ /g' | sort | uniq -c | sort -rn > /tmp/log_analysis/errors_counts.txt || true
head -n 40 /tmp/log_analysis/errors_counts.txt > /tmp/log_analysis/errors_top40.txt || true
# Extract timestamps (try ISO 8601, RFC-like "Mon DD HH:MM:SS", and "YYYY-MM-DD HH:MM:SS") and compute hourly distribution
awk '
{
  line=$0;
  ts="";
  if (match(line, /[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/)) ts=substr(line, RSTART, RLENGTH);
  else if (match(line, /[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}/)) ts=substr(line, RSTART, RLENGTH);
  else if (match(line, /[A-Z][a-z]{2} [ 0-9][0-9] [0-9]{2}:[0-9]{2}:[0-9]{2}/)) ts=substr(line, RSTART, RLENGTH);
  if (ts=="") print "NO_TS";
  else {
    # normalize to an hour key: try to extract hour portion
    if (match(ts, /[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:/)) {
      hour=substr(ts,1,13); # YYYY-MM-DDTHH
    } else if (match(ts, /[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:/)) {
      hour=substr(ts,1,13); # YYYY-MM-DD HH
    } else if (match(ts, /[A-Z][a-z]{2} [ 0-9][0-9] [0-9]{2}:/)) {
      hour=substr(ts,1,15); # Mon DD HH
    } else hour=ts;
    print hour;
  }
}' /tmp/log_analysis/errors_raw.txt | sort | uniq -c | sort -rn > /tmp/log_analysis/errors_by_hour.txt || true

# Prepare a short file list for the report
cat /tmp/log_analysis/logfiles.txt > /tmp/log_analysis/file_list.txt || true

# Create a draft report summarizing counts and top errors
{
  echo "Log analysis report - last 24 hours";
  echo "Generated: $(date -u +'%Y-%m-%dT%H:%M:%SZ')";
  echo "";
  echo "Files scanned:";
  echo "----------------";
  if [ -s /tmp/log_analysis/file_list.txt ]; then
    sed -n '1,200p' /tmp/log_analysis/file_list.txt;
  else
    echo "(no log files found)";
  fi
  echo "";
  echo "Total matching error lines:";
  echo "-------------------------------";
  if [ -z "$ERROR_LINES" ] || [ "$ERROR_LINES" = "0" ]; then
    echo "0";
  else
    echo "$ERROR_LINES";
  fi
  echo "";
  echo "Top distinct error messages (top 40 by exact text):";
  echo "------------------------------------------------";
  if [ -s /tmp/log_analysis/errors_top40.txt ]; then
    sed -n '1,200p' /tmp/log_analysis/errors_top40.txt;
  else
    echo "(no matching error lines)";
  fi
  echo "";
  echo "Hourly distribution (approximate keys):";
  echo "-------------------------------------";
  if [ -s /tmp/log_analysis/errors_by_hour.txt ]; then
    sed -n '1,200p' /tmp/log_analysis/errors_by_hour.txt;
  else
    echo "(no timestamped error lines)";
  fi
  echo "";
  echo "Notes & patterns:";
  echo "------------------";
  if [ -s /tmp/log_analysis/errors_top40.txt ]; then
    # heuristic pattern detections
    if grep -qi "connection refused\|ECONNREFUSED\|connection reset" /tmp/log_analysis/errors_only.txt; then
      echo "- Connection/refused/reset errors detected; may indicate network/service availability issues.";
    fi
    if grep -qi "timeout" /tmp/log_analysis/errors_only.txt; then
      echo "- Timeout errors present; could be slow downstream services.";
    fi
    if grep -qi "outofmemory\|oom\|java.lang.OutOfMemoryError" /tmp/log_analysis/errors_only.txt; then
      echo "- OOM errors detected; investigate memory usage in containers/processes.";
    fi
    if grep -qi "permission denied|EACCES" /tmp/log_analysis/errors_only.txt; then
      echo "- Permission denied errors present; may be file permission or access control issues.";
    fi
    if grep -qi "traceback|exception|stacktrace" /tmp/log_analysis/errors_only.txt; then
      echo "- Application exceptions / stack traces observed; check application logs for root causes.";
    fi
  else
    echo "No explicit error lines matched our search patterns (error/exception/fail/fatal/traceback).";
  fi
  echo "";
  echo "Sample error lines (up to 40):";
  echo "-----------------------------";
  if [ -s /tmp/log_analysis/errors_raw.txt ]; then
    sed -n '1,200p' /tmp/log_analysis/errors_raw.txt | sed -n '1,40p';
  else
    echo "(no matching error lines)";
  fi
} > /work/report.md

# Also copy analysis artifacts for inspection
cp -a /tmp/log_analysis /work/log_analysis_output || true

# Print a short completion message
echo "REPORT_WRITTEN:/work/report.md";
exit 0
